//refAssemblies: System.Net.Http.dll, System.IO.Compression.dll, System.IO.Compression.ZipFile.dll, System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Graceful stop: the server saves the world and exits on ONE Ctrl+C (a second one quits without saving).
// Windows: a Ctrl+C sent through its console does not reach it (it ignores console Ctrl+C events), so windows-kill
// delivers the event straight to the server process. Linux (Wine): a native SIGINT to the server's Wine process
// becomes the console Ctrl+C. Only the server process of THIS service is signalled.
const string binary = "AbioticFactorServer-Win64-Shipping";
const int maxWaitSeconds = 120;

var rootPath = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\');
var root = rootPath + Path.DirectorySeparatorChar;
var rootSlash = rootPath.Replace('\\', '/') + "/";

List<int> ServerPids()
{
    var pids = new List<int>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var p in Process.GetProcessesByName(binary))
        {
            try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) pids.Add(p.Id); }
            catch { } // exited meanwhile
        }
        return pids;
    }
    // Wine shows the executable as Z:\<root>\...\AbioticFactorServer-Win64-Shipping.exe in the command line.
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var args = File.ReadAllText(Path.Combine(dir, "cmdline")).Replace('\0', ' ').Replace('\\', '/');
            if (args.Contains(binary + ".exe", StringComparison.OrdinalIgnoreCase) && args.Contains(rootSlash, StringComparison.Ordinal)
                && !args.Contains("start.exe", StringComparison.OrdinalIgnoreCase))
                pids.Add(pid);
        }
        catch { } // gone meanwhile
    }
    pids.Sort();
    return pids;
}

var targets = ServerPids();
if (targets.Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}

if (System.OperatingSystem.IsWindows())
{
    // windows-kill is kept in the hidden .tca folder of the service and downloaded once.
    var toolDir = Path.Combine(rootPath, ".tca");
    var killExe = Path.Combine(toolDir, "windows-kill.exe");
    if (!File.Exists(killExe))
    {
        const string url = "https://github.com/ElyDotDev/windows-kill/releases/download/1.1.4/windows-kill_1.1.4_release.zip";
        const string entryPath = "windows-kill_x64_1.1.4_lib_release/windows-kill.exe";
        try
        {
            Directory.CreateDirectory(toolDir);
            using (var http = new HttpClient())
            using (var zip = new ZipArchive(new MemoryStream(await http.GetByteArrayAsync(url, ThisCancellationToken))))
            {
                var entry = zip.GetEntry(entryPath);
                if (entry == null) throw new Exception("'" + entryPath + "' is not in the archive.");
                entry.ExtractToFile(killExe, true);
            }
        }
        catch (Exception ex)
        {
            ScriptConsole.WriteLine((object)("Could not download windows-kill (" + ex.Message + "); the panel stops the server without saving."));
            return;
        }
    }
    foreach (var pid in targets)
    {
        // CreateNoWindow gives windows-kill a console of its own, so the event never reaches the monitor.
        var psi = new ProcessStartInfo(killExe, new[] { "-SIGINT", pid.ToString() })
        {
            UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true,
            WorkingDirectory = toolDir
        };
        using (var killer = Process.Start(psi))
        {
            var output = (await killer.StandardOutput.ReadToEndAsync()).Trim();
            await killer.WaitForExitAsync(ThisCancellationToken);
            if (killer.ExitCode != 0) ScriptConsole.WriteLine((object)("windows-kill: " + output));
        }
    }
}
else
{
    // One SIGINT to the main server process (the lowest pid); its worker threads share it.
    targets = targets.Take(1).ToList();
    using (var kill = Process.Start(new ProcessStartInfo("kill", new[] { "-INT", targets[0].ToString() }) { UseShellExecute = false }))
        kill.WaitForExit();
}

ScriptConsole.WriteLine((object)("Asked the server (" + string.Join(", ", targets) + ") to save and exit."));
for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (!ServerPids().Any(targets.Contains))
    {
        ScriptConsole.WriteLine((object)("The server exited after " + second + " s."));
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));
